    def binomial_coeff(m, k):
        # Efficiently calculates C(m, k) using multiplicative formula
        if k > m - k:
            k = m - k  # Take advantage of symmetry
        res = 1
        for i in range(1, k + 1):
            res = res * (m - k + i) // i
        return res

    C_2n_n = binomial_coeff(2 * n, n)
    return C_2n_n // (n + 1)
